-- 0003_orders_backfill.sql
--
-- Full order-history backfill for PokeSouq (pokesouq.myshopify.com).
-- One row per Shopify order, for the `orders` capture table that the
-- WhatsApp / social attribution work joins against on phone_e164.
--
-- Rows            : 3824
-- Date range      : 2023-05-01T15:28:13Z .. 2026-09-14T12:21:31Z (UTC, as returned by Shopify)
-- Source          : Shopify Admin GraphQL API (orders connection, sortKey
--                   CREATED_AT, query "created_at:>=2023-01-01"), paginated
--                   in pages of 100 until hasNextPage was false.
-- Generated on    : 2026-09-14
--
-- Phone selection
--   phone_e164 is taken from the FIRST non-null/non-empty of, in order:
--     1. customer.phone
--     2. order.phone
--     3. shippingAddress.phone
--     4. billingAddress.phone
--   The chosen value is then normalised to E.164. If the chosen value does
--   not normalise confidently the row gets NULL -- no fallback to a later
--   field, and no country code is ever guessed.
--
-- Normalisation rules applied (conservative by design)
--   * spaces, hyphens, brackets, dots and slashes stripped
--   * a leading run of '+' collapsed to a single '+'
--   * a leading '00' replaced by '+'
--   * '+' followed by 8-15 digits (first digit 1-9) is kept as-is
--   * bare 9-digit local starting with 5        -> +971<9 digits>
--   * bare 10-digit local starting with 05      -> +971<last 9 digits>
--   * bare 12-digit starting 971 then a 5       -> +971<last 9 digits>
--     (the country code is literally present, so this is not a guess)
--   * anything else -> NULL
--
-- NULL phone rows : 6 of 3824
--   These are orders where the preferred phone field was absent, empty, or a
--   value that could not be normalised without guessing (too few/too many
--   digits, free text, local formats with no recoverable country code).
--   They are loaded anyway so the order history is complete; they simply
--   cannot participate in the phone join.
--
-- is_first_order is deliberately NOT populated here. It is left NULL and is
-- meant to be computed in SQL after load, e.g.
--   UPDATE orders o SET is_first_order = (o.placed_at = f.first_at)
--   FROM (SELECT phone_e164, min(placed_at) AS first_at
--           FROM orders WHERE phone_e164 IS NOT NULL
--          GROUP BY phone_e164) f
--   WHERE o.phone_e164 = f.phone_e164;
--
-- The script is idempotent: every statement upserts on shopify_order_id.

BEGIN;

ON CONFLICT (shopify_order_id) DO UPDATE SET
  shopify_customer_id = excluded.shopify_customer_id,
  phone_e164 = excluded.phone_e164,
  placed_at = excluded.placed_at,
  total = excluded.total,
  currency = excluded.currency,
  captured_at = now();

ON CONFLICT (shopify_order_id) DO UPDATE SET
  shopify_customer_id = excluded.shopify_customer_id,
  phone_e164 = excluded.phone_e164,
  placed_at = excluded.placed_at,
  total = excluded.total,
  currency = excluded.currency,
  captured_at = now();

